<template><Layout><div class="breadcrumb"><Link :href="route('resources')">Resources</Link><span>›</span>Subcategories</div><div class="page-header list-header"><div><div class="eyebrow">PRODUCT GROUPS</div><h1>Subcategories</h1><p>{{ total }} groups across {{ groups.length }} main categories.</p></div><Link :href="route('sub-categories.create')" class="primary-button">＋ New subcategory</Link></div><div class="listing-toolbar standalone"><div class="list-search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg><input v-model="query" placeholder="Search subcategories…"/></div><span>{{ total }} results</span></div><section class="subcategory-groups"><article v-for="group in filteredGroups" :key="group.id" class="subcategory-panel"><header><span class="category-image"><img :src="group.icon" alt=""/></span><div><h2>{{ group.name }}</h2><p>{{ group.sub_categories.length }} subcategories</p></div><Link :href="route('main-categories.edit',{id:group.id})">Edit parent →</Link></header><div class="subcategory-grid"><Link v-for="item in group.sub_categories" :key="item.id" :href="route('sub-categories.edit',{id:item.id})"><span class="sub-image"><img :src="item.icon" alt=""/></span><div><strong>{{ item.name }}</strong><small>{{ item.purchase_count || 0 }} purchases</small></div><b>›</b></Link></div></article><div v-if="!filteredGroups.length" class="listing-panel empty-state"><div>⌕</div><strong>No subcategories found</strong><p>Create a subcategory or try another search.</p></div></section></Layout></template>
<script setup>import {ref,computed,onMounted} from 'vue';import {usePage} from '@inertiajs/vue3';import {useToast} from 'vue-toastification';import {route} from 'ziggy-js';import Layout from '../../Layouts/Layout.vue';const props=defineProps({data:Object});const groups=computed(()=>props.data?.data||[]),query=ref('');const filteredGroups=computed(()=>groups.value.map(g=>({...g,sub_categories:(g.sub_categories||[]).filter(s=>s.name.toLowerCase().includes(query.value.toLowerCase()))})).filter(g=>g.sub_categories.length));const total=computed(()=>filteredGroups.value.reduce((sum,g)=>sum+g.sub_categories.length,0));const page=usePage(),toast=useToast();onMounted(()=>{if(page.props.flash?.success)toast.success(page.props.flash.success)});</script>
